void setup() {
  pinMode(13, OUTPUT);
  pinMode(2, INPUT_PULLUP);
  Serial.begin(9600);
}

void loop() {
  int knopka = digitalRead(2);
  if (knopka == LOW) {
    digitalWrite(13, LOW);
    Serial.println("Режим: диагностика");
  } else {
    digitalWrite(13, HIGH);
    Serial.println("Режим: мониторинг");
  }
  delay(150);
}
